	@Override
	public JSONArray getAssigneProjectNames(String phaseName) {
		System.out.println("Inside PmsDaoImpl getAssigneProjectNames method");

		JSONArray jsonArray = new JSONArray();

		try {
			// Fetch distinct phases
			String phaseQueryStr = "SELECT DISTINCT FUNCTION_NAME FROM functionmaster";
			if (phaseName != null && !phaseName.isEmpty()) {
				phaseQueryStr += " WHERE FUNCTION_NAME LIKE :phaseName";
			}
			phaseQueryStr += " ORDER BY CASE WHEN FUNCTION_NAME LIKE 'DEVELOPMENT%' THEN 1 "
					+ "WHEN FUNCTION_NAME LIKE 'Enhancement%' THEN 2 "
					+ "WHEN FUNCTION_NAME LIKE 'Implementation%' THEN 4 " + "ELSE 3 END, FUNCTION_NAME";

			Query phaseQuery = getSession().createSQLQuery(phaseQueryStr);
			if (phaseName != null && !phaseName.isEmpty()) {
				phaseQuery.setParameter("phaseName", phaseName + "%");
			}

			List<Object> phases = phaseQuery.list();

			int phaseId = 0;
			int productId = 0;
			int toolId = 0;
			int projectId = 0;

			for (Object phase : phases) {
				phaseId++;
				String phaseNameN = phase.toString();

				// Create phase node
				JSONObject phaseNode = new JSONObject();
				phaseNode.put("id", "phase" + phaseId);
				phaseNode.put("parent", "#");
				phaseNode.put("text", phaseNameN);
				jsonArray.put(phaseNode);

				// Retrieve product suits based on the phase
				Query productQuery = getSession().createSQLQuery("SELECT DISTINCT PRODUCTSUIT FROM DaywiseTask "
						+ "WHERE FUNCTION_NAME IN (SELECT FUNCTION_NAME FROM functionmaster WHERE FUNCTION_NAME LIKE :phaseName) "
						+ "ORDER BY PRODUCTSUIT ASC");
				productQuery.setParameter("phaseName", phaseNameN + "%");
				List<String> productSuits = productQuery.list();

				for (String productSuit : productSuits) {
					productId++;
					JSONObject productNode = new JSONObject();
					productNode.put("id", "product" + productId);
					productNode.put("parent", "phase" + phaseId);
					productNode.put("text", productSuit);
					jsonArray.put(productNode);

					// Retrieve security solutions based on the phase and product suit
					Query securityQuery = getSession().createSQLQuery("SELECT DISTINCT PRODUCTTOOL FROM DaywiseTask "
							+ "WHERE PRODUCTSUIT = :productSuit AND FUNCTION_NAME IN (SELECT FUNCTION_NAME FROM functionmaster WHERE FUNCTION_NAME LIKE :phaseName) "
							+ "ORDER BY PRODUCTTOOL ASC");
					securityQuery.setParameter("productSuit", productSuit);
					securityQuery.setParameter("phaseName", phaseNameN + "%");
					List<String> securitySolutions = securityQuery.list();

					for (String securitySolution : securitySolutions) {
						toolId++;
						JSONObject securityNode = new JSONObject();
						securityNode.put("id", "tool" + toolId);
						securityNode.put("parent", "product" + productId);
						securityNode.put("text", securitySolution);
						jsonArray.put(securityNode);

						// Retrieve project names based on the phase, product suit, and security
						// solution
//	                    Query projectQuery = getSession().createSQLQuery(
//	                        "SELECT DISTINCT CUSTOMERNAME FROM DaywiseTask "
//	                        + "WHERE PRODUCTSUIT = :productSuit AND PRODUCTTOOL = :securitySolution "
//	                        + "AND FUNCTION_NAME IN (SELECT FUNCTION_NAME FROM functionmaster WHERE FUNCTION_NAME LIKE :phaseName) "
//	                        + "GROUP BY CUSTOMERNAME " 
//	                        + "HAVING SUM(WEIGHTAGE) <= 100 " 
//	                        + "ORDER BY CUSTOMERNAME ASC"
//	                    );

						Query projectQuery = getSession().createSQLQuery("SELECT DISTINCT CUSTOMERNAME,"
								+ "SUM(WEIGHTAGE) AS TotalWeightage, "
								+ "ROUND((SUM(WEIGHTAGE) / (SELECT SUM(WEIGHTAGE) "
								+ "FROM DaywiseTask WHERE PRODUCTSUIT = :productSuit "
								+ "AND PRODUCTTOOL = :securitySolution "
								+ "AND FUNCTION_NAME IN (SELECT FUNCTION_NAME FROM functionmaster WHERE FUNCTION_NAME LIKE :phaseName))) * 100, 2) AS Percentage "
								+ "FROM DaywiseTask "
								+ "WHERE PRODUCTSUIT = :productSuit AND PRODUCTTOOL = :securitySolution "
								+ "AND FUNCTION_NAME IN (SELECT FUNCTION_NAME FROM functionmaster WHERE FUNCTION_NAME LIKE :phaseName) "
								+ "AND STATUS IN('Completed')" + "GROUP BY CUSTOMERNAME "
								+ "HAVING SUM(WEIGHTAGE) <= 100 " + "ORDER BY CUSTOMERNAME ASC");

						projectQuery.setParameter("productSuit", productSuit);
						projectQuery.setParameter("securitySolution", securitySolution);
						projectQuery.setParameter("phaseName", phaseNameN + "%");
//	                    List<String> projectNames = projectQuery.list();
//
//	                    for (String projectName : projectNames) {
//	                        projectId++;
//	                        JSONObject projectNode = new JSONObject();
//	                        projectNode.put("id", "Project" + projectId);
//	                        projectNode.put("parent", "tool" + toolId);
//	                        projectNode.put("text", "Customer Name : " + projectName);
//	                        jsonArray.put(projectNode);
//	                    }

						double roundedPercentage = 0.0;

						List<Object[]> results = projectQuery.list();

						double percentage = 0.0;

						for (Object[] result : results) {
							if (result.length > 0 && result[0] instanceof String) {
								String projectName = (String) result[0];
								percentage = (double) result[1];

								roundedPercentage = Math.round(percentage * 100.0) / 100.0;

								String formattedPercentage = String.format("%.2f", roundedPercentage);
								String redPercentage = "<font color='green'>" + formattedPercentage + "%</font>";

								projectId++;
								JSONObject projectNode = new JSONObject();
								projectNode.put("id", "Project" + projectId);
								projectNode.put("parent", "tool" + toolId);
//	                            projectNode.put("text", "Customer Name : " + projectName);
//	                            projectNode.put("text", "Customer Name: " + projectName + " ( " + String.format("%.2f", roundedPercentage) + "% )");
								projectNode.put("text", "Customer Name: " + projectName + " ( " + redPercentage + " )");
								jsonArray.put(projectNode);
							} else {
								System.out.println("Unexpected data type or empty array.");
							}
						}
					}
				}
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
		System.out.println("Inside getAssigneProjectNames method: " + jsonArray);
		return jsonArray;
	}

