	@Override
	public String saveTaskDetails(String pONumb, String date, String customername, String productLicense,
			String implementorName, String implementorNumber, String cusImplementorEmail, String salesManagerName,
			String endCustomerName, String endCustomerNumber, String paymentTermsPO, String description,
			String alldata) {
		// TODO Auto-generated method stub
		String status = null;
		try {
			// Adding Sr_no
			Criteria crit = sessionFactory.getCurrentSession().createCriteria(AssignTaskDetails.class)
					.setProjection(Projections.max("SR_NO"));
			Integer srno1 = (Integer) crit.uniqueResult();
			int srno = 0;
			System.out.println("dadde" + alldata);
			//// //System.out.println(" SRNO IS: " + srno1);

			if (srno1 != null) {
				srno = srno1.intValue();
				srno = srno + 1;
				//// //System.out.println("IN IF SRNO IS: " + srno);
			} else {
				srno = 1;
				//// //System.out.println("IN ELSE SRNO IS: " + srno);
			}

//		SimpleDateFormat formatter = new SimpleDateFormat("dd-MM-yyyy HH:mm");
//		String mysqldate = formatter.format(date);
//		System.out.println("Sql Date" + formatter.format(date));

			AssignTaskDetails task = new AssignTaskDetails();

			task.setSR_NO(srno);

			task.setPoNumber(pONumb);
			task.setDate(date);
			task.setCustomerName(customername);
			task.setProductLicense(productLicense);
			task.setCustomerImplementorName(implementorName);
			task.setCustomerImplementorContact(implementorNumber);
			task.setCustomerImplementorEmail(cusImplementorEmail);
			task.setSalesManagerName(salesManagerName);
			task.setCustomerSPOCName(endCustomerName);
			task.setCustomerSPOCName(endCustomerNumber);
			task.setPaymentTerms(paymentTermsPO);
			task.setDescription(description);
			task.setAddRowDetails(alldata);

			System.out.println("alll data " + task);
			getSession().save(task);
			status = "success";

		} catch (Exception e) {
			e.printStackTrace();
		}
		return status;
	}

