	@Override
	public String ApproveRdDetailsBySI(String crno, String status) {

		String output = "null";
		String getVL_STATUS = "NA";

		String updateStatus = "";
		String swalStatus = "";
		int srno = Integer.parseInt(crno);

		try {

			Criteria q1 = sessionFactory.getCurrentSession().createCriteria(requirementDocument.class);
			q1.add(Restrictions.eq("SR_NO", srno));

			List<requirementDocument> vpList = q1.list();

			System.out.println("All CI-scheduleList are::: " + vpList);
			for (requirementDocument a : vpList) {

				getVL_STATUS = a.getRDStatus();

			}
			System.out.println("getVL_STATUS ----- " + getVL_STATUS);

			if (getVL_STATUS.equalsIgnoreCase("RD Pending For Approval")) {

				updateStatus = "RD Approved By SI";
				swalStatus = "success";
			}

			System.out.println("updateStatus " + updateStatus);
			// Update Purchase Order
			if (!updateStatus.equalsIgnoreCase("")) {
				String hql = "update requirementDocument set RDStatus= :com1 WHERE SR_NO= :crno";
				Query q = sessionFactory.getCurrentSession().createQuery(hql);
				q.setParameter("com1", updateStatus);
				q.setParameter("crno", srno);

				int i = q.executeUpdate();
				if (i > 0) {
					System.out.println("Updated");
					output = swalStatus;
				} else {
					System.out.println("Not Updated");
					output = "fail";
				}
			}

		} catch (Exception e3) {
			e3.printStackTrace();
		}

		return output;
	}

