	@Override
	public JSONArray getTesterTaskList(String uname, String userfullname) {
		List<String> statusList = new ArrayList<String>();
		statusList.add("Pending");
		statusList.add("Completed");
		statusList.add("Other");

		// daywise task table
		Criteria q = sessionFactory.getCurrentSession().createCriteria(DaywiseTask.class);
		q.add(Restrictions.in("STATUS", statusList));
		q.add(Restrictions.in("TESTER_NAME", userfullname));

		List<DaywiseTask> ds = q.list();

		JSONArray array1 = new JSONArray();
//			JSONArray array=null;

		for (DaywiseTask a : ds) {
			JSONArray array = new JSONArray();
			array.put("<button class='btn btn-info' id='viewOption'  name='Doem' onclick='ApprovedTASK(\""
					+ a.getSR_NO() + "\")'><i class='fa fa-eye'></i></button>");
			array.put(a.getSTATUS());
			if (a.getMODULE_NAME() == null || a.getMODULE_NAME().contentEquals("")) {
				array.put("NA");
			} else {
				array.put(a.getMODULE_NAME());
			}
			if (a.getTESTER_NAME() == null || a.getTESTER_NAME().contentEquals("")) {
				array.put("NA");
			} else {
				array.put(a.getTESTER_NAME());
			}
			if (a.getASSIGNBY() == null || a.getASSIGNBY().contentEquals("")) {
				array.put("NA");
			} else {
				array.put(a.getASSIGNBY());
			}
			if (a.getSTART_DATE() == null || a.getSTART_DATE().contentEquals("")) {
				array.put("NA");
			} else {
				array.put(a.getSTART_DATE());
			}
			if (a.getEND_DATE() == null || a.getEND_DATE().contentEquals("")) {
				array.put("NA");
			} else {
				array.put(a.getEND_DATE());
			}

			array1.put(array);
		}
		System.out.println("final value  " + array1);
		return array1;

	}

