	@Override
	public String updateModifyDate(String crno, String tid, String status, String remark, String end_Date,
			String fullname, String role, String designation) {
		System.out.println(crno + " ssfs " + status + " s" + remark + tid + " ssfssd ");
		String reStatus = null;
		int srno = Integer.parseInt(crno);
		int i = 0;
		int count = 0;

//	Query checkData = getSession().createQuery("from  MainTaskDetails where T_NO='" + tid + "'");
//	List<Object> mainTask = checkData.list();

//	if (!mainTask.isEmpty()) {
//		Query query = sessionFactory.getCurrentSession()
//				.createQuery("update MainTaskDetails set STATUS ='" + status + "' where T_NO ='" + tid + "'");
//		i = query.executeUpdate();
//	} else {

		DateFormat dateFormat = null;
		dateFormat = new SimpleDateFormat("dd.MM.yyyy HH:mm"); // Corrected the format for minutes
		Date date = null;
		date = new Date();
		String current_dateTime = dateFormat.format(date);
		DaywiseTask daywisetask = sessionFactory.getCurrentSession().get(DaywiseTask.class, srno);

		Query query = sessionFactory.getCurrentSession()
				.createQuery("update DaywiseTask set END_DATE='" + end_Date + "'  where SR_NO ='" + srno + "'");
		i = query.executeUpdate();

		if (daywisetask != null) {
			String updateDateCountStr = daywisetask.getUpdateDateCount();
			if (updateDateCountStr != null) {
				count = Integer.parseInt(updateDateCountStr);
			}
		}

		// Increment updateDateCount if updateEnd_Date is provided
		if (end_Date != null && !end_Date.isEmpty()) {
			count++;
			String countAsString = String.valueOf(count);
			daywisetask.setUpdateDateCount(countAsString);
			daywisetask.setUpdateEnd_Date(end_Date);
			daywisetask.setUpdateTimeDate(current_dateTime);
			daywisetask.setUpdateDate_Status("Pending for approval");
		}
//	}

		if (i == 0) {
			reStatus = "error";
		} else {
			reStatus = "success";

		}

		System.out.println("dao status " + reStatus);
		return reStatus;

	}

	@Override
	public JSONArray getMyCompletedTaskList(String uname, String userfullname, String role) {

		List<String> statusList = new ArrayList<String>();
//		statusList.add("Pending");
//		statusList.add("Other");
		statusList.add("Completed");

		// daywise task table
		Criteria q = sessionFactory.getCurrentSession().createCriteria(DaywiseTask.class);
		q.add(Restrictions.in("STATUS", statusList));
		q.addOrder(Order.desc("SR_NO"));
		List<DaywiseTask> ds = q.list();

		JSONArray array1 = new JSONArray();
//					JSONArray array=null;

		for (DaywiseTask a : ds) {
			if (userfullname.equals(a.getDEVELOPER_NAME())) {
				JSONArray array = new JSONArray();
				array.put(
						"<button class='btn btn-info' id='viewOption'  name='Doem' onclick='DevCompletedTaskDetails(\""
								+ a.getSR_NO() + "\")'><i class='fa fa-eye'></i></button>");
				array.put(a.getSTATUS());
				array.put(a.getCUSTOMERNAME() + " - " + a.getSR_NO());
				array.put(a.getMODULE_NAME());
				array.put(a.getDEVELOPER_NAME());
				if (a.getTEAM_LEADER() == null || a.getTEAM_LEADER().contentEquals("")) {
					array.put("NA");
				} else {
					array.put(a.getTEAM_LEADER());
				}

				array.put(a.getASSIGNBY());
				array.put(a.getSTART_DATE());
				array.put(a.getEND_DATE());

				if (a.getDESCRIPTION() == null || a.getDESCRIPTION().contentEquals("")) {
					array.put("NA");
				} else {
					array.put(a.getDESCRIPTION());
				}

				array1.put(array);
			}
		}

		System.out.println("final value completed " + array1);
		return array1;
	}

