	@Override
	public JSONArray getMGRdelayActivityByProj(String projectName, String userfullname, String role) {
		JSONArray jsonArray = new JSONArray();
		Query query = null;
		try {
			System.out.println("roleees " + role);
			if (role.equalsIgnoreCase("Support_Manager")) {

				query = getSession().createSQLQuery(
						"SELECT CUSTOMERNAME, PRODUCTSUIT, PRODUCTTOOL, FUNCTION_NAME, DESCRIPTION, TEAM_LEADER, DEVELOPER_NAME, END_DATE "
								+ "FROM DaywiseTask " + "WHERE (MANAGER_NAME= '" + userfullname
								+ "' OR DEVELOPER_NAME = '" + userfullname + "' ) " + "AND CUSTOMERNAME = '"
								+ projectName + "' " + "AND STATUS = 'Pending' "
								+ "AND STR_TO_DATE(END_DATE, '%d.%m.%Y') < CURRENT_DATE()");

			} else {
				query = getSession().createSQLQuery(
						"SELECT CUSTOMERNAME, PRODUCTSUIT, PRODUCTTOOL, FUNCTION_NAME, DESCRIPTION, TEAM_LEADER, DEVELOPER_NAME, END_DATE "
								+ "FROM DaywiseTask "
								+ "WHERE (PRODUCTTOOL in(select SECURITY_SOLTION from ProductMaster where ImplementerName = '"
								+ userfullname + "') OR MANAGER_NAME= '" + userfullname + "' ) "
								+ "AND CUSTOMERNAME = '" + projectName + "' " + "AND STATUS = 'Pending' "
								+ "AND STR_TO_DATE(END_DATE, '%d.%m.%Y') < CURRENT_DATE()");
			}
			List<Object[]> result = query.list();
			for (Object[] row : result) {
				String customerName = (String) row[0];
				String productSuit = (String) row[1];
				String productTool = (String) row[2];
				String function = (String) row[3];
				String description = (String) row[4];
				String teamLeader = (String) row[5];
				String developer = (String) row[6];
				String endDateString = (String) row[7];

				// Parse string to LocalDate
				DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd.MM.yyyy");
				LocalDate endDate = LocalDate.parse(endDateString, formatter);

				long delayDays = ChronoUnit.DAYS.between(endDate, LocalDate.now());

				JSONObject taskObject = new JSONObject();
				taskObject.put("CustomerName", customerName);
				taskObject.put("ProductSuit", productSuit);
				taskObject.put("ProductTool", productTool);
				taskObject.put("Function", function);
				taskObject.put("Description", description);
				taskObject.put("TeamLeader", teamLeader);
				taskObject.put("Developer", developer);
				taskObject.put("EndDate", endDateString);
				taskObject.put("DelayDays", delayDays);

				jsonArray.put(taskObject);
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
		System.out.println("jsonArray: " + jsonArray);
		return jsonArray;
	}

