	@Override
	public String updateMultipleEndDate(String fullname, String role, String designation, String updatedDates) {

		String status = null;

		try {

			System.out.println("updatedDates " + updatedDates);

			String[] data = updatedDates.split(",");
			System.out.println("Dataaa " + data);

			for (int i = 0; i < data.length; i = i + 2) {
				String srno = data[i];
				int crno = Integer.parseInt(srno);
				String endDate = data[i + 1];
				System.out.println("Srno " + srno + " , date " + endDate);

				String hql = "update DaywiseTask set updateDate_Status='Pending for approval', updateEnd_Date= :date  WHERE SR_NO= :crno";
				Query q = sessionFactory.getCurrentSession().createQuery(hql);

				q.setParameter("crno", crno);
				q.setParameter("date", endDate);

				int a = q.executeUpdate();
				if (a > 0) {
					System.out.println("Updated");
					status = "success";
				} else {
					System.out.println("Not Updated");
					status = "error";
				}
			}
		} catch (Exception e) {
			status = "error";
		}
		return status;
	}

	@Override
	public String approveMultipleEndDate(String fullname, String role, String designation, String checkedIds) {

		String status = null;
		try {

			System.out.println("updatedDates " + checkedIds);

			String[] data = checkedIds.split(",");
			System.out.println("Dataaa " + data);

			DateFormat dateFormat = null;
			dateFormat = new SimpleDateFormat("dd.MM.yyyy HH:mm"); // Corrected the format for minutes
			Date date = null;
			date = new Date();
			String current_dateTime = dateFormat.format(date);

			for (int i = 0; i < data.length; i++) {
				String srno = data[i];
				int crno = Integer.parseInt(srno);
				System.out.println("Srno " + srno);

				Criteria qu = sessionFactory.getCurrentSession().createCriteria(DaywiseTask.class);
				qu.add(Restrictions.in("SR_NO", crno));
				List<DaywiseTask> ds = qu.list();

				String newEndDate = "";
				String updateCountFirst = "";
				int updateCounts = 0;

				for (DaywiseTask a : ds) {
					newEndDate = a.getUpdateEnd_Date();
					updateCountFirst = a.getUpdateDateCount();
				}
				try {

					if (updateCountFirst.contentEquals("") || updateCountFirst == null) {
						updateCounts = 0;
					} else {
						updateCounts = Integer.parseInt(updateCountFirst) + 1;
					}
				} catch (Exception e) {
					e.printStackTrace();
					updateCounts = 1;
				}

				System.out.println("updateCount swf " + updateCounts);
				String updateCount = String.valueOf(updateCounts);

				String hql = "update DaywiseTask set updateDate_Status='Date Approved', updateTimeDate= :curdate , END_DATE= :endDate, updateDateCount= :updateCount  WHERE SR_NO= :crno";
				Query q = sessionFactory.getCurrentSession().createQuery(hql);

				q.setParameter("crno", crno);
				q.setParameter("endDate", newEndDate);
				q.setParameter("curdate", current_dateTime);
				q.setParameter("updateCount", updateCount);

				int a = q.executeUpdate();
				if (a > 0) {
					System.out.println("Updated");
					status = "success";
				} else {
					System.out.println("Not Updated");
					status = "error";
				}

			}
		} catch (Exception e) {
			e.printStackTrace();
			status = "error";
		}

		return status;
	}

