	@Override
	public String getTreeMasterDetails(String product_suite, String security_solution, String project_name) {
		String status = null;

		try {
			// Adding Sr_no
			Criteria crit = sessionFactory.getCurrentSession().createCriteria(ProjectNameMaster.class)
					.setProjection(Projections.max("SR_NO"));
			Integer srno1 = (Integer) crit.uniqueResult();
			int srno = 0;
			//// //System.out.println(" SRNO IS: " + srno1);

			if (srno1 != null) {
				srno = srno1.intValue();
				srno = srno + 1;
				//// //System.out.println("IN IF SRNO IS: " + srno);
			} else {
				srno = 1;
				//// //System.out.println("IN ELSE SRNO IS: " + srno);
			}

			Query query = getSession().createQuery("from ProjectNameMaster where  PRODUCT_SUIT='" + product_suite
					+ "' AND SECURITY_SOLTION='" + security_solution + "' AND PROJECT_NAME='" + project_name + "'");

			ProjectNameMaster data = (ProjectNameMaster) query.uniqueResult(); //// //System.out.println("data:" +
																				//// data);

			if (data != null) {
				status = "duplicate";
			} else {
				ProjectNameMaster projectnameMaster = new ProjectNameMaster();

				projectnameMaster.setSR_NO(srno);
				projectnameMaster.setPRODUCT_SUIT(product_suite);
				projectnameMaster.setSECURITY_SOLTION(security_solution);
				projectnameMaster.setPROJECT_NAME(project_name);

				getSession().save(projectnameMaster);
				status = "success";
			}
		} catch (Exception e) {
			e.printStackTrace();
		}
		return status;
	}

