	@Override
	public String savefileUploadKey(MultipartFile[] fileUploadKey) {
		System.out.println("in savefileUploadKey " + fileUploadKey.length);

		String imageFilePath = "C:\\SCM\\";
		File dir = new File(imageFilePath);

		if (!dir.exists())
			dir.mkdirs();

		for (int j = 0; j < fileUploadKey.length; j++) {
			MultipartFile file = fileUploadKey[j];

			try {
				if (!file.isEmpty()) {
					String fileName1 = file.getOriginalFilename();
					String fileName = fileName1.replaceAll(" ", "_");
					double fileSize = file.getSize();

					if (fileSize > 0) {
						String name = FilenameUtils.removeExtension(fileName);
						String ext = FilenameUtils.getExtension(fileName);
						String newFileName = name + "." + ext; // Generate unique name

						System.out.println("generate File " + newFileName);
						File serverFile = new File(dir, newFileName);
						file.transferTo(serverFile);

						System.out.println("Server File Location: " + serverFile.getAbsolutePath());
					}
				}
			} catch (Exception e) {
				System.out.println("Exception occurred while processing file: " + e.getMessage());
				// Log the exception or handle it according to your requirement
			}
		}

		return "Success"; // or some appropriate value
	}

