	@Override
	public String updateMultipleStartEndDate(String fullname, String role, String designation, String updatedStartDates,
			String updatedEndDates, String updateDatesReason) {

		String status = null;

		try {
			System.out.println("updatedStartDates: " + updatedStartDates);

			String[] startData = updatedStartDates.split(",");

			if (startData.length % 4 != 0) {
				System.out.println("Data format error: Expected sets of 4 entries for each record.");
				return "error";
			}

			for (int i = 0; i < startData.length; i += 4) {

				String srnoString = startData[i];
				int srno = Integer.parseInt(srnoString);
				String startDate = startData[i + 1];
				String endDate = startData[i + 2];
				String reason = startData[i + 3];

				reason = reason.replace('"', ' ');

//				            DaywiseTask d=new DaywiseTask();
//				            String exStartDate=d.getSTART_DATE().toString();
//				            String exEndDate=d.getEND_DATE().toString();

				String hqlUpdateStart = "update DaywiseTask set updateDate_Status='Pending for approval', updateStarts_Date= :startDate,updateEnd_Date= :endDate , updateDates_Reason= :reviseReason WHERE SR_NO= :srno";
				Query updateStartQuery = sessionFactory.getCurrentSession().createQuery(hqlUpdateStart);
				updateStartQuery.setParameter("srno", srno);
				updateStartQuery.setParameter("startDate", startDate);

				updateStartQuery.setParameter("endDate", endDate);
				updateStartQuery.setParameter("reviseReason", reason);

				int startUpdateCount = updateStartQuery.executeUpdate();
				status = (startUpdateCount > 0) ? "success" : "error";
				System.out.println(startUpdateCount > 0 ? "Start Date Updated" : "Start Date Not Updated");

			}
		} catch (NumberFormatException e) {
			System.out.println("Error parsing SR_NO to Integer: " + e.getMessage());
			status = "error";
		} catch (Exception e) {
			status = "error";
			e.printStackTrace();
		}
		return status;
	}

