	// 07/11
	@Override
	public JSONArray getEmployeesHiredThisMonth() {

		System.out.println("inside getEmployeesHiredThisMonth dao");

		JSONArray array1 = null;
		boolean flag = false;

		Query query = null;
		try {
			array1 = new JSONArray();

			query = sessionFactory.getCurrentSession().createQuery(
					"from loginmaster WHERE YEAR(STR_TO_DATE(REGISTRATION_DATE, '%d.%m.%Y')) = YEAR(CURRENT_DATE)\r\n"
							+ "AND MONTH(STR_TO_DATE(REGISTRATION_DATE, '%d.%m.%Y')) = MONTH(CURRENT_DATE)");

			List<loginmaster> rdh = query.list();

			for (loginmaster a : rdh) {
//							if (fullname.equals(a.getDEVELOPER_NAME())) {
				JSONArray array = new JSONArray();

				array.put(a.getFULL_NAME());
				array.put(a.getUSERNAME());
				array.put(a.getDEPARTMENT());
				array.put(a.getDESIGNATION());
				array.put(a.getREGISTRATION_DATE());

				String[] experiencedDesignations = { "Manager", "Head", "Senior", "Lead", "Director", "Chief", "VP",
						"CFO", "President", "Sr" };

				String[] fresherDesignations = { "Trainee", "Jr.", "Junior", "Executive", "Assistant", "Support",
						"Cordinator" };

				String designationLower = a.getDESIGNATION().toLowerCase();

				for (String exp : experiencedDesignations) {
					if (designationLower.contains(exp.toLowerCase())) {

						array.put("Experienced");
						flag = true;
					}
				}

				for (String fresher : fresherDesignations) {
					if (designationLower.contains(fresher.toLowerCase())) {

						array.put("Fresher");
						flag = true;
					}
				}

				if (flag == false) {
					array.put("NA");
				}

				array1.put(array);
			}

		} catch (Exception e) {
			e.printStackTrace();
		}
		System.out.println("Activities history " + array1);

		return array1;
	}

	// 07/11
	@Override
	public JSONArray getHiredComapreCounts() {

		System.out.println("inside getEmployeesHiredThisMonth dao");

		JSONArray array1 = null;
		boolean flag = false;

		Query query = null;
		try {
			array1 = new JSONArray();

			query = sessionFactory.getCurrentSession().createQuery(
					"SELECT COUNT(*) AS hired_count, MONTH(STR_TO_DATE(REGISTRATION_DATE, '%d.%m.%Y')) AS month,YEAR(STR_TO_DATE(REGISTRATION_DATE, '%d.%m.%Y')) AS YEAR FROM loginmaster\r\n"
							+ "WHERE REGISTRATION_DATE IS NOT NULL AND (YEAR(STR_TO_DATE(REGISTRATION_DATE, '%d.%m.%Y')) = YEAR(CURRENT_DATE) \r\n"
							+ "     AND MONTH(STR_TO_DATE(REGISTRATION_DATE, '%d.%m.%Y')) = MONTH(CURRENT_DATE)) \r\n"
							+ "    OR\r\n"
							+ "    (YEAR(STR_TO_DATE(REGISTRATION_DATE, '%d.%m.%Y')) = YEAR(CURRENT_DATE) \r\n"
							+ "     AND MONTH(STR_TO_DATE(REGISTRATION_DATE, '%d.%m.%Y')) = MONTH(CURRENT_DATE) - 1) \r\n"
							+ ")\r\n"
							+ "GROUP BY YEAR(STR_TO_DATE(REGISTRATION_DATE, '%d.%m.%Y')), MONTH(STR_TO_DATE(REGISTRATION_DATE, '%d.%m.%Y'))\r\n"
							+ "ORDER BY year DESC, month DESC");

			List<Object[]> results = query.list();

			int currentMonthCount = 0;
			int previousMonthCount = 0;

			if (results.size() > 0) {
				for (Object[] row : results) {

					int month = ((Number) row[1]).intValue();
					int hiredCount = ((Number) row[0]).intValue();

					if (month == LocalDate.now().getMonthValue()) {
						currentMonthCount = hiredCount;
					} else if (month == LocalDate.now().minusMonths(1).getMonthValue()) {
						previousMonthCount = hiredCount;
					}
				}
			}

			int difference = currentMonthCount - previousMonthCount;

			Map<String, Integer> result = new HashMap<>();
			result.put("currentMonth", currentMonthCount);
			result.put("previousMonth", previousMonthCount);
			result.put("difference", difference);

			array1.put(result);

		} catch (Exception e) {
			e.printStackTrace();
		}
		System.out.println("Activities history::::::: " + array1);

		return array1;
	}

