	@Override
	public JSONArray ActivitiesCompletedcountNewMan(String role, String userfullname, String methodName) {
		JSONArray array1 = new JSONArray();
		System.out.println("in ActivitiesCompletedcountNew");
		Query q = null;

		try {
			if (methodName.equalsIgnoreCase("TotalProjects")) {
				System.out.println("in totallll");

				if (role.equalsIgnoreCase("Support_Manager")) {
					q = getSession().createSQLQuery(
							"select CUSTOMERNAME, MANAGER_NAME, PRODUCTSUIT, PRODUCTTOOL, FUNCTION_NAME, DESCRIPTION, TEAM_LEADER, DEVELOPER_NAME, TaskUpdateDate, END_DATE, STATUS, updateDateCount from DaywiseTask WHERE FUNCTION_NAME IN('Implementation','POC','UAT','Go Live') ");

				} else if (role.equalsIgnoreCase("Implementor")) {
					q = getSession().createSQLQuery(
							"select CUSTOMERNAME, MANAGER_NAME, PRODUCTSUIT, PRODUCTTOOL, FUNCTION_NAME, DESCRIPTION, TEAM_LEADER, DEVELOPER_NAME, TaskUpdateDate, END_DATE, STATUS, updateDateCount from DaywiseTask WHERE (PRODUCTTOOL in(select SECURITY_SOLTION from ProductMaster where ImplementerName = '"
									+ userfullname + "') OR MANAGER_NAME='" + userfullname + "' ) ");
				} else {
					q = getSession().createSQLQuery(
							"select CUSTOMERNAME, MANAGER_NAME, PRODUCTSUIT, PRODUCTTOOL, FUNCTION_NAME, DESCRIPTION, TEAM_LEADER, DEVELOPER_NAME, TaskUpdateDate, END_DATE, STATUS, updateDateCount from DaywiseTask  ");
				}

				List<Object[]> results = q.list();

				for (Object[] row : results) {
					JSONArray array = new JSONArray();

					array.put(row[0]); // Customer_Name
					array.put(row[1]); // Manager Name
					array.put(row[2]); // Product_Suite
					array.put(row[3]); // Product_Tool
					array.put(row[4]); // Function_Name
					array.put(row[5]); // Description
					array.put(row[6]); // TEAM_LEADER
					array.put(row[7]); // DEVELOPER_NAME
					array.put(row[8]); // TaskUpdateDate
					array.put(row[9]); // END_DATE
					array.put(row[10]); // STATUS
					array.put(row[11]); // updateDateCount

					System.out.println("Row 10: " + row[10]);
					try {
						if (row[10].equals("Pending")) {
							String endDateString = row[9].toString();

							if (!(endDateString.equals("NA") || endDateString.isEmpty())) {
								SimpleDateFormat dateFormat = new SimpleDateFormat("dd.MM.yyyy");

								Date currentDate = new Date();
								Date endDate = dateFormat.parse(endDateString);

								System.out.println("endDate " + endDate + " , " + currentDate);

								if (currentDate.after(endDate)) {
									array.put("Delayed");
								} else if (endDate.after(currentDate)) {
									array.put("Pending");
								}
							} else {
								array.put("Pending");
							}
						} else {
							array.put(row[10]);
						}
					} catch (Exception e) {
						e.printStackTrace();
						array.put("Error processing status");
					}

					array1.put(array);
				}
			} else {
				System.out.println("inside else");

				if (role.equalsIgnoreCase("Support_Manager")) {
					q = getSession().createSQLQuery(
							"select CUSTOMERNAME, MANAGER_NAME, PRODUCTSUIT, PRODUCTTOOL, FUNCTION_NAME, DESCRIPTION, TEAM_LEADER, DEVELOPER_NAME, TaskUpdateDate, END_DATE, STATUS, updateDateCount from DaywiseTask WHERE FUNCTION_NAME IN('Implementation','POC','UAT','Go Live') ORDER BY CUSTOMERNAME");
				} else if (role.equalsIgnoreCase("Implementor")) {
					q = getSession().createSQLQuery(
							"select CUSTOMERNAME, MANAGER_NAME, PRODUCTSUIT, PRODUCTTOOL, FUNCTION_NAME, DESCRIPTION, TEAM_LEADER, DEVELOPER_NAME, TaskUpdateDate, END_DATE, STATUS, updateDateCount from DaywiseTask WHERE (PRODUCTTOOL in(select SECURITY_SOLTION from ProductMaster where ImplementerName = '"
									+ userfullname + "') OR MANAGER_NAME='" + userfullname
									+ "' ) ORDER BY CUSTOMERNAME");
				} else {
					q = getSession().createSQLQuery(
							"select CUSTOMERNAME, MANAGER_NAME, PRODUCTSUIT, PRODUCTTOOL, FUNCTION_NAME, DESCRIPTION, TEAM_LEADER, DEVELOPER_NAME, TaskUpdateDate, END_DATE, STATUS, updateDateCount from DaywiseTask ORDER BY CUSTOMERNAME");
				}

				List<Object[]> results = q.list();
				for (Object[] row : results) {
					JSONArray array = new JSONArray();
					for (Object cell : row) {
						array.put(cell);
					}
					array1.put(array);
				}
			}
		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}

		System.out.println("NIIIII" + array1);
		return array1;
	}

