	@Override
	public JSONArray getListForDeletedActivities(String prodSuit, String secTool, String custName, String projectStatus,
			String uname) {

		JSONArray array1 = new JSONArray();

		Query query1 = sessionFactory.getCurrentSession()
				.createQuery("select FULL_NAME FROM loginmaster where USERNAME='" + uname + "'");
		String full_name = (String) query1.uniqueResult();

		Query query = sessionFactory.getCurrentSession()
				.createQuery("FROM DaywiseTask where PRODUCTSUIT='" + prodSuit + "' AND PRODUCTTOOL='" + secTool
						+ "' AND CUSTOMERNAME='" + custName + "' AND STATUS='" + projectStatus + "' AND MANAGER_NAME='"
						+ full_name + "'");

		List<DaywiseTask> dp = query.list();

		for (DaywiseTask a : dp) {

			JSONArray array = new JSONArray();

			array.put("<input type='checkbox' name='taskCheckBoxes' id='" + a.getSR_NO()
					+ "' onclick='checkIndividual()'>");
//				

			if (a.getAssign_date() == null || a.getAssign_date().contentEquals("")) {
				array.put("NA");
			} else {
				array.put(a.getAssign_date());
			}

			array.put(a.getSTATUS());
//				
			try {
				if (a.getTask_ID().equals("")) {
					array.put(a.getCUSTOMERNAME() + "-" + a.getSR_NO());
				} else {
					array.put(a.getTask_ID());
				}

			} catch (Exception e) {

				array.put(a.getCUSTOMERNAME() + "-" + a.getSR_NO());
			}

			array.put(a.getCUSTOMERNAME());
			array.put(a.getPRODUCTSUIT());
			array.put(a.getPRODUCTTOOL());
			array.put(a.getDESCRIPTION());
			array.put(a.getMODULE_NAME());
			array.put(a.getDEVELOPER_NAME());

			if (a.getTEAM_LEADER() == null || a.getTEAM_LEADER().contentEquals("")) {
				array.put("NA");
			} else {
				array.put(a.getTEAM_LEADER());
			}

			array.put(a.getASSIGNBY());
			array.put(a.getSTART_DATE());
			array.put(a.getEND_DATE());
			array1.put(array);

		}

		System.out.println("final value  " + array1);
		return array1;
	}

	// 16/11
	@Override
	public String deleteActivitiesData(String checkedIds) {
		String status = null;

		try {

			System.out.println("checkedIds " + checkedIds);

			String[] data = checkedIds.split(",");
			System.out.println("Dataaa " + Arrays.toString(data));

			for (String srno : data) {
				int crno = Integer.parseInt(srno);
				System.out.println("Srno " + crno);

				Criteria qu = sessionFactory.getCurrentSession().createCriteria(DaywiseTask.class);
				qu.add(Restrictions.eq("SR_NO", crno));
				List<DaywiseTask> ds = qu.list();

				if (!ds.isEmpty()) {

					DaywiseTask taskToDelete = ds.get(0);

					sessionFactory.getCurrentSession().delete(taskToDelete);
					System.out.println("Deleted SR_NO: " + crno);
				} else {
					System.out.println("No record found for SR_NO: " + crno);
				}
			}
			status = "success";

		} catch (Exception e) {
			e.printStackTrace();
			status = "error";
		}

		return status;
	}

