	@Override
	public JSONArray getTodaysProgressModalData(String uname, String crno, String tid) {
		int srno = Integer.parseInt(crno);

		LocalDate currentDate = LocalDate.now();
		DateTimeFormatter outputCurrentDate = DateTimeFormatter.ofPattern("dd.MM.yyyy");
		String formattedDate = currentDate.format(outputCurrentDate);

		JSONArray array1 = new JSONArray();

		// daywise table

		Criteria q = sessionFactory.getCurrentSession().createCriteria(DaywiseTask.class);

		List<DaywiseTask> ds = q.list();

		for (DaywiseTask a : ds) {
			if (srno == (a.getSR_NO())) {
				JSONArray array = new JSONArray();

				array.put(a.getFUNCTION_NAME());
				array.put(a.getMODULE_NAME());
				array.put(a.getCUSTOMERNAME());
				array.put(a.getPRODUCTTOOL());
				array.put(a.getPRODUCTSUIT());
				array.put(a.getDESCRIPTION());

				array.put(formattedDate);

				array1.put(array);
			}
		}

		System.out.println("Single record  " + array1);
		return array1;
	}

	@Override
	public String saveTodaysProgress(String functionNameModal, String moduleNameModal, String customerNameModal,
			String productNameModal, String productSuiteNameModal, String taskDescModal, String dateModal,
			String progressModal, String crno, String userfullname) {
		String status = null;
		try {
			Session s = getSession();

			String query = "FROM Update_Todays_Progress WHERE TASK_ID = :crno AND DATE = :date";
			Update_Todays_Progress existingProgress = (Update_Todays_Progress) s.createQuery(query)
					.setParameter("crno", crno).setParameter("date", dateModal).uniqueResult();

			if (existingProgress != null) {
				status = "duplicate";
			} else {

				Update_Todays_Progress utp = new Update_Todays_Progress();
				utp.setTASK_ID(crno);
				utp.setFUNCTION_NAME(functionNameModal);
				utp.setMODULE_NAME(moduleNameModal);
				utp.setCUSTOMER_NAME(customerNameModal);
				utp.setPRODUCT_NAME(productNameModal);
				utp.setPRODUCT_SUITE(productSuiteNameModal);
				utp.setTASK_DESC(taskDescModal);
				utp.setDATE(dateModal);
				utp.setTODAYS_PROGRESS(progressModal);

				utp.setFULL_NAME(userfullname);
				utp.setTASK_TYPE("General");
				utp.setSTATUS("In-Progress");

				s.save(utp);
				status = "success";
			}
		} catch (Exception e) {
			e.printStackTrace();
			status = "error";
		}

		System.out.println("Status: " + status);
		return status;
	}

	@Override
	public JSONArray dashboardTableForHeadProject(String uname, String role, String designation) {
		System.out.println("inside dashboardTableForHeadProject dao");
		JSONArray array1 = new JSONArray();
		try {

			Query q = getSession().createSQLQuery(
					"SELECT vlx_id, endCustomer, customername, vlx_status, poraisedate, submittedby, FormAB_status, formABfilldate, formABfillby, Form3_status, approveddate, PO_Second_Approver FROM PurchaseOrder where vlx_status NOT IN ('Manual PO Raised By SI','Purchase Order Approved') ORDER BY CAST(SUBSTRING(vlx_id, 4, LENGTH(vlx_id)) AS UNSIGNED) DESC");
			List<Object[]> result = q.list();

			for (Object[] row : result) {
				JSONArray array = new JSONArray();

				String vlx_id = row[0].toString();
				String endCustomer = row[1] != null ? row[1].toString() : "";
				String customername = row[2] != null ? row[2].toString() : "";
				String poCustomerName = vlx_id + "-" + (endCustomer.isEmpty() ? customername : endCustomer);
				array.put(poCustomerName);

				String vlx_status = row[3] != null ? row[3].toString() : "";
				String poraisedate = row[4] != null ? row[4].toString() : "";
				String submittedby = row[5] != null ? row[5].toString() : "";
				String poInitiator = "";

				Query name = getSession()
						.createSQLQuery("select FULL_NAME from loginmaster where USERNAME='" + submittedby + "'");
				String subBy = (String) name.uniqueResult();

				System.out.println("poraisedate:::" + poraisedate + " submittedby:::" + submittedby);

				if ("Sent For Purchase Order Approval".equals(vlx_status)) {
					String[] po_raiseDate = poraisedate.split(" ");
					poInitiator = po_raiseDate[0] + " - " + subBy;

					System.out.println("poInitiatorpoInitiator:::" + poInitiator);
					array.put(poInitiator);
				} else {
					array.put("NA");
				}

				String FormAB_status = row[6] != null ? row[6].toString() : "";
				String formABfilldate = row[7] != null ? row[7].toString() : "";
				String formABfillby = row[8] != null ? row[8].toString() : "";
				String poApprover = "";
				if ("FORMA/B Submitted".equals(FormAB_status)) {
					String[] formAB_fillD = formABfilldate.split(" ");
					poApprover = formAB_fillD[0] + " - " + formABfillby;

					array.put(poApprover);

//	                String temp_val=null;
//	                System.out.println(temp_val.equals("abc"));
				} else {
					array.put("NA");
				}

//	            String Form3_status = row[9] != null ? row[9].toString() : "";
//	            String planOfAction = Form3_status;
//	            array.put(planOfAction);

				// changes
				String Form3_status = row[9] != null ? row[9].toString() : "";

				Query poa = getSession().createSQLQuery(
						"SELECT f3.Form3FillDate, f3.Form3Fillby FROM purchaseorder po INNER JOIN form3 f3 ON f3.VP_id = po.vlx_id");
				List<Object[]> result1 = poa.list();

				String Form3FillDate = "";
				String Form3Fillby = "";

				for (Object[] ob_data : result1) {

					Form3FillDate = ob_data[0].toString();
					Form3Fillby = ob_data[1] != null ? ob_data[1].toString() : "";
				}

				Query name1 = getSession()
						.createSQLQuery("select FULL_NAME from loginmaster where USERNAME='" + Form3Fillby + "'");
				String form3_submitted_by = (String) name1.uniqueResult();
				String planOfAction = "";

				if (Form3_status.contains("FORM3 Submitted By")) {

					String[] approved_dateN = Form3FillDate.split(" ");

					planOfAction = approved_dateN[0] + " - " + form3_submitted_by;

					array.put(planOfAction);
				} else {
					array.put("NA");
				}
				// changes

				String approveddate = row[10] != null ? row[10].toString() : "";
				String approvedby = row[11] != null ? row[11].toString() : "";
				String approvedBy = "";
//	            String[] approved_dateN=approveddate.split(" ");
//	            String approvedBy = approved_dateN[0] + " - " + approvedby;
				if ("Purchase Order Approved".equals(vlx_status)) {
					String[] approved_dateN = approveddate.split(" ");
					approvedBy = approved_dateN[0] + " - " + approvedby;

					array.put(approvedBy);
				} else {
					array.put("NA");
				}

				array1.put(array);
				System.out.println("array1array1array1array1::::" + array1);
			}

		} catch (Exception e) {
			e.printStackTrace();
		}

		System.out.println("array1: " + array1);
		return array1;
	}

