	@Override
	public String saveIssueCustomizationTask(String customerName, String productsuit, String productname,
			String moduleName, String enddate, String priority, String description, String expectedOutput,
			String userfullname, String uname, String role, String designation, String taskData) {

		String status = null;
		String taskStatus = "Yet to Assign";
		String productTool = null;

		System.out.println("customerName: " + customerName + ", productname: " + productname);
		System.out.println("Received taskData: " + taskData);

		try {

			Criteria crit = sessionFactory.getCurrentSession().createCriteria(CustomizationTask.class)
					.setProjection(Projections.max("SR_NO"));
			Integer srno1 = (Integer) crit.uniqueResult();
			int srno = (srno1 != null) ? srno1 + 1 : 1;

			/* ===================== FIX START ===================== */
			JSONArray jsonArray = new JSONArray(taskData);

			for (int i = 0; i < jsonArray.length(); i++) {

				JSONObject obj = jsonArray.getJSONObject(i);

				productTool = obj.getString("productTool");
				/* ===================== FIX END ===================== */

				System.out.println("Extracted productTool: " + productTool);

				Criteria duplicateCheckCrit = sessionFactory.getCurrentSession().createCriteria(CustomizationTask.class)
						.add(Restrictions.eq("PRODUCTSUIT", obj.getString("productSuite")))
						.add(Restrictions.eq("PRODUCTTOOL", productTool))
						.add(Restrictions.eq("CUSTOMERNAME", obj.getString("custName")))
						.add(Restrictions.eq("MODULE_NAME", obj.getString("moduleName")))
						.add(Restrictions.eq("END_DATE", obj.getString("exDate")))
						.add(Restrictions.eq("DESCRIPTION", obj.getString("desc"))).setMaxResults(1);

				CustomizationTask existingTask = (CustomizationTask) duplicateCheckCrit.uniqueResult();

				if (existingTask != null) {

					System.out.println("Duplicate task found, skipping save.");
					status = "duplicate";
					continue;

				} else {

					CustomizationTask customizationTask = new CustomizationTask();
					customizationTask.setSR_NO(srno);
					customizationTask.setPRODUCTSUIT(obj.getString("productSuite"));
					customizationTask.setCUSTOMERNAME(obj.getString("custName"));
					customizationTask.setPRODUCTTOOL(productTool);
					customizationTask.setMODULE_NAME(obj.getString("moduleName"));
					customizationTask.setEND_DATE(obj.getString("exDate"));
					customizationTask.setPRIORITY(obj.getString("priorityType"));
					customizationTask.setDESCRIPTION(obj.getString("desc"));
					customizationTask.setEXPECTED_OUTPUT(obj.getString("exOutput"));
					customizationTask.setASSIGNBY(userfullname);
					customizationTask.setSTATUS(taskStatus);

					DateFormat dateFormat = new SimpleDateFormat("dd-MM-yyyy HH:mm");
					String current_date = dateFormat.format(new Date());
					customizationTask.setSUBMITTED_DATE(current_date);

					Query qName1 = sessionFactory.getCurrentSession().createQuery(
							"select ImplementerName from ProductMaster where SECURITY_SOLTION='" + productTool + "'");
					List<String> Mnames = qName1.list();
					String ManagerName = Mnames.get(0);

					customizationTask.setMANAGER_NAME(ManagerName);

					if (role.equalsIgnoreCase("Support_Manager")) {
						customizationTask.setSUPPORT_TEAM_LEADER("NA");
					} else if (role.equalsIgnoreCase("Support") && (designation.equalsIgnoreCase("Team Leader")
							|| designation.equalsIgnoreCase("Sr Team Leader")
							|| designation.equalsIgnoreCase("Jr. Team Leader"))) {

						customizationTask.setSUPPORT_TEAM_LEADER(userfullname);

					} else if (role.equalsIgnoreCase("Support")) {

						try {
							Query qName = sessionFactory.getCurrentSession().createQuery(
									"select Team_Leader from TlMaster where Developer='" + userfullname + "'");
							List<String> Tnames = qName.list();
							customizationTask.setSUPPORT_TEAM_LEADER(Tnames.get(0));
						} catch (Exception e) {
							customizationTask.setSUPPORT_TEAM_LEADER("NA");
						}
					}

					try {
						Query qName2 = sessionFactory.getCurrentSession()
								.createQuery("select FULL_NAME from loginmaster where ROLE_TYPE='Support_Manager'");
						List<String> SMnames = qName2.list();
						customizationTask.setSUPPORT_MANAGER_NAME(SMnames.get(0));
					} catch (Exception e) {
						customizationTask.setSUPPORT_MANAGER_NAME("NA");
					}

					getSession().save(customizationTask);
					srno++;
				}

				status = "success";
			}

		} catch (Exception e) {
			status = "error";
			e.printStackTrace();
		}

		return status;
	}

