	@Override
	public JSONArray getTaskChart(String uname, String userfullname, String role, String solution) {

		System.out.println("in methodarray1 Pie " + solution);

		JSONArray array1 = new JSONArray();
		JSONArray finalOutput = new JSONArray();
		String hql1 = null;

		try {
			if (solution.equalsIgnoreCase("NA")) {
				if (role.equalsIgnoreCase("Implementor")) {
					hql1 = "SELECT PRODUCTTOOL, COUNT(*) AS count FROM customizationtask WHERE MANAGER_NAME='"
							+ userfullname + "' GROUP BY PRODUCTTOOL ORDER BY count DESC, PRODUCTTOOL DESC LIMIT 3";
				} else {
					hql1 = "SELECT PRODUCTTOOL, COUNT(*) AS count FROM customizationtask GROUP BY PRODUCTTOOL ORDER BY count DESC, PRODUCTTOOL DESC LIMIT 3";
				}
			} else {
				String solutions = solution.replace(",", "','");
				if (role.equalsIgnoreCase("Implementor")) {
					hql1 = "SELECT PRODUCTTOOL, COUNT(*) AS count FROM customizationtask WHERE MANAGER_NAME='"
							+ userfullname + "' AND PRODUCTTOOL='" + solutions + "' GROUP BY PRODUCTTOOL";
				} else {
					hql1 = "SELECT PRODUCTTOOL, COUNT(*) AS count FROM customizationtask WHERE PRODUCTTOOL IN ('"
							+ solutions + "') GROUP BY PRODUCTTOOL ";
				}
			}

			Query query1 = sessionFactory.getCurrentSession().createSQLQuery(hql1);

			List<Object[]> toolList = query1.list();

			String maxTools = "";
			JSONArray toolArr = new JSONArray();
			for (Object[] result : toolList) {
				if (maxTools.equals("")) {
					maxTools = (String) result[0];
				} else {
					maxTools = maxTools + "','" + (String) result[0];
				}
			}

			System.out.println("maxTools Toolssss :: " + maxTools);

			String hql = "SELECT PRODUCTTOOL, COUNT(CASE WHEN STATUS = 'Yet to Assign' THEN 1 END), COUNT(CASE WHEN STATUS = 'Assigned' THEN 1 END), COUNT(CASE WHEN STATUS = 'Developed' THEN 1 END), COUNT(CASE WHEN STATUS = 'Tested' THEN 1 END), COUNT(CASE WHEN STATUS = 'Ready to Deliver' THEN 1 END) FROM CustomizationTask WHERE STATUS != 'Close' AND PRODUCTTOOL IN ('"
					+ maxTools + "') GROUP BY PRODUCTTOOL ";

			Query query = sessionFactory.getCurrentSession().createQuery(hql);

			List<Object[]> dataList = query.list();
			JSONArray arrTools = new JSONArray();
			JSONArray arrfinal = new JSONArray();

			// Creating an array for each task type
			JSONArray yetToAssignData = new JSONArray();
			JSONArray assignedData = new JSONArray();
			JSONArray developedData = new JSONArray();
			JSONArray testedData = new JSONArray();
			JSONArray readyToDeliverData = new JSONArray();

			if (!dataList.isEmpty()) {

				for (Object[] result : dataList) {
					String tool = (String) result[0];

					Long yetToAssign = (Long) result[1];
					Long assigned = (Long) result[2];
					Long developed = (Long) result[3];
					Long tested = (Long) result[4];
					Long readyToDeliver = (Long) result[5];

					arrTools.put(tool);

					yetToAssignData.put(yetToAssign);
					assignedData.put(assigned);
					developedData.put(developed);
					testedData.put(tested);
					readyToDeliverData.put(readyToDeliver);
				}

				arrfinal.put(new JSONObject().put("name", "Yet to Assign").put("data", yetToAssignData));
				arrfinal.put(new JSONObject().put("name", "Assigned").put("data", assignedData));
				arrfinal.put(new JSONObject().put("name", "Developed").put("data", developedData));
				arrfinal.put(new JSONObject().put("name", "Tested").put("data", testedData));
				arrfinal.put(new JSONObject().put("name", "Ready to Deliver").put("data", readyToDeliverData));

				System.out.println("arrfinal ::: " + arrfinal);

				finalOutput.put(arrTools);
				finalOutput.put(arrfinal);

			}

			System.out.println("Final JSON Output: " + finalOutput);

		} catch (Exception e) {
			System.out.println("Exception.barrrrrr..  " + e);
			e.printStackTrace();
		}

		System.out.println("fina barrr " + finalOutput);
		return finalOutput;

	}

