	public JSONArray getOpTaskByCustomer(String role, String designation, String customer, String userfullname) {
		System.out.println("customerrrr:: " + customer);
		System.out.println("customerrrr 22:: " + URLDecoder.decode(customer));
		String cName = URLDecoder.decode(customer);

		JSONArray array = null;
		JSONArray array1 = null;
		String endDate = null;
		Query q = null;
		try {
			array1 = new JSONArray();

			if (role.equalsIgnoreCase("Implementor")) {
				q = sessionFactory.getCurrentSession().createQuery("from CustomizationTask WHERE CUSTOMERNAME='" + cName
						+ "' AND STATUS!='Close' AND MANAGER_NAME='" + userfullname + "' ");
			} else if (role.equalsIgnoreCase("Developer")) {
				q = sessionFactory.getCurrentSession()
						.createQuery("from CustomizationTask WHERE CUSTOMERNAME='" + cName
								+ "' AND STATUS!='Close' AND (TEAM_LEADER='" + userfullname + "' OR DEVELOPER_NAME='"
								+ userfullname + "'  OR TESTER_NAME='" + userfullname + "') ");
			} else {
				q = sessionFactory.getCurrentSession()
						.createQuery("from CustomizationTask WHERE CUSTOMERNAME='" + cName + "' AND STATUS!='Close' ");
			}

			List<CustomizationTask> dataList = q.list();

			for (CustomizationTask a : dataList) {
				array = new JSONArray();

				array.put(a.getPRODUCTTOOL());
				array.put(a.getDESCRIPTION());
				if (a.getSTATUS().equalsIgnoreCase("Yet To Assign")) {
					array.put("-");
					endDate = "-";
				} else {
					array.put(a.getASSIGNED_DATE());
					endDate = a.getASSIGNED_DATE();
				}

				array.put(a.getMANAGER_NAME());

				array.put(a.getSTATUS());
				if (a.getSTATUS().equalsIgnoreCase("Assigned") || a.getSTATUS().equalsIgnoreCase("Tested")) {

					if (a.getDEVELOPER_NAME() == null || a.getDEVELOPER_NAME().contentEquals("")) {
						array.put(a.getTEAM_LEADER());
					} else {
						array.put(a.getDEVELOPER_NAME());
					}

				} else if (a.getSTATUS().equalsIgnoreCase("Yet To Assign")) {
					array.put(a.getMANAGER_NAME());

				} else if (a.getSTATUS().equalsIgnoreCase("Ready to Deliver")) {
					array.put(a.getASSIGNBY());

				} else if (a.getSTATUS().equalsIgnoreCase("Developed")) {
					array.put(a.getTESTER_NAME());
				}

				try {
					DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd-MM-yyyy");
					LocalDate endDate1 = LocalDate.parse(endDate.toString(), formatter);
					long delayDays = ChronoUnit.DAYS.between(endDate1, LocalDate.now());

					if (delayDays > 0) {
						array.put(delayDays);
					} else {
						array.put("0");
					}
				} catch (Exception e) {
					array.put("0");
				}

				array1.put(array);
			}

		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}
		System.out.println("array1array1" + array1);
		return array1;
	}

