	@Override
	public String submitCompliance(String productSuit, String securitytool, String customerName, String refNO,
			String complianceFile, String role, String userfullname, String designation, String description,
			String salesManager) {
		String status1 = null;

		System.out.println("complianceFile : " + complianceFile);
		String ManagerName = null;
		String Fhead = null;
		String AMDM = null;

		LocalDate currentDate = LocalDate.now();
		DateTimeFormatter formatter1 = DateTimeFormatter.ofPattern("dd-MM-yyyy");
		String formattedDate = currentDate.format(formatter1);

		try {
			Session s = getSession();
			int srno = 0;
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(ComplianceUpload.class)
						.setProjection(Projections.max("SR_NO"));
				Integer srno1 = (Integer) crit.uniqueResult();

				if (srno1 != null) {
					srno = srno1.intValue() + 1;

				} else {
					srno = 1;
				}
			} catch (Exception e) {

				e.printStackTrace();
			}

			Query query = sessionFactory.getCurrentSession().createQuery(
					"from ComplianceUpload where PRODUCTSUIT=:PRODUCT_SUIT AND PRODUCTTOOL=:Product_Tool AND CUSTOMERNAME=:Customer_Name AND REF_NO=:refNO");
			query.setParameter("PRODUCT_SUIT", productSuit);
			query.setParameter("Product_Tool", securitytool);
			query.setParameter("Customer_Name", customerName);
			query.setParameter("refNO", refNO);
//			query.setParameter("sts",complianceFile);
			List data = query.list();

			if (!data.isEmpty()) {
				status1 = "duplicate~0";
			} else {
				ComplianceUpload comp = new ComplianceUpload();

				comp.setSR_NO(srno);
				comp.setPRODUCTSUIT(productSuit);
				comp.setPRODUCTTOOL(securitytool);
				comp.setCUSTOMERNAME(customerName);
				comp.setREF_NO(refNO);
				comp.setDESCRIPTION(description);
				comp.setSALES_MANAGER(salesManager);

				String newName = "_RFPfile_" + srno + ".xlsx";
				String newFilename = complianceFile.replace(".xlsx", "") + newName;

				comp.setCOMPLIANCE_FILE(newFilename);
				comp.setSTATUS("Yet to Assign");

				try {
					Query qName = sessionFactory.getCurrentSession().createQuery(
							"select ImplementerName from ProductMaster where SECURITY_SOLTION='" + securitytool + "'");
					List<String> Mnames = qName.list();
					ManagerName = Mnames.get(0);
				} catch (Exception e) {
					ManagerName = "NA";
				}

				try {
					Query fHeadQ = sessionFactory.getCurrentSession()
							.createQuery("select F_HEAD from TEAM_MASTER where SOLUTION='" + securitytool + "'");
					List<String> Fheads = fHeadQ.list();
					Fhead = Fheads.get(0);
				} catch (Exception e) {
					Fhead = "NA";
				}

				try {
					Query AMDMQ = sessionFactory.getCurrentSession()
							.createQuery("select AM_DM from TEAM_MASTER where SOLUTION='" + securitytool + "'");
					List<String> Ams = AMDMQ.list();
					AMDM = Ams.get(0);
				} catch (Exception e) {
					AMDM = "NA";
				}

				comp.setMANAGER_NAME(ManagerName);
				comp.setF_HEAD(Fhead);
				comp.setAM_DM(AMDM);
				comp.setASSIGNBY(userfullname);
				comp.setSUBMITTED_DATE(formattedDate);

				getSession().save(comp);
				status1 = "success~" + srno;
			}
		} catch (Exception e) {
			status1 = "error~0";
			e.printStackTrace();
		}

		return status1;
	}

