					int crno1 = Integer.parseInt(srno1);
					String endDate1 = data1[j + 1];
					System.out.println("Srno " + srno1 + " , date " + endDate1);

					String hql1 = "update ComplianceTask set ASSIGNED_DATE= :date  WHERE SR_NO= :crno1";
