						+ "COUNT(CASE WHEN STATUS = 'Tested' THEN 1 END),"
						+ "COUNT(CASE WHEN STATUS = 'Ready to Deliver' THEN 1 END)" + "FROM ComplianceTask  "
						+ "GROUP BY PRODUCTTOOL " + "ORDER BY PRODUCTTOOL";
