	@Override
	public String saveTeamMaster(String productsuit, String productname, String functionalHead, String am_dmName,
			String tlname, String mappedWith, String userfullname, String phaseType) {

		System.out.println("innn saveTeamMaster" + userfullname);

		LocalDate currentDate = LocalDate.now();
		DateTimeFormatter formatter1 = DateTimeFormatter.ofPattern("dd-MM-yyyy");
		String formattedDate = currentDate.format(formatter1);

		String status = null;
		String solnId = null;

		try {
			Session s = getSession();
			int srno = 0;

			String implementorUsername = "";
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(TEAM_MASTER.class)
						.setProjection(Projections.max("SR_NO"));
				Integer srno1 = (Integer) crit.uniqueResult();

				if (srno1 != null) {
					srno = srno1.intValue() + 1;

				} else {
					srno = 1;
				}
			} catch (Exception e) {

				e.printStackTrace();
			}

//			Query query = sessionFactory.getCurrentSession().createQuery(
//					"from TEAM_MASTER where ImplementerName=:IMPLEMENTERNAME AND Team_Leader=:Team_Lead AND Developer=:developer");

//			query.setParameter("IMPLEMENTERNAME", implementerName);
//			query.setParameter("Team_Lead", tlname);
//			query.setParameter("developer", developer);

//			List data = query.list();

//			if (!data.isEmpty()) {
//				status = "duplicate";
//			} else {
			TEAM_MASTER team = new TEAM_MASTER();

			team.setSR_NO(srno);
			team.setPRODUCT_SUIT(productsuit);
			team.setSOLUTION(productname);
			;

			if (functionalHead.equals("null") || functionalHead.isEmpty()) {
				team.setF_HEAD("NA");
			} else {
				team.setF_HEAD(functionalHead);
			}

			if (tlname.equals("null") || tlname.isEmpty()) {
				team.setTEAM_LEADER("NA");
			} else {
				team.setTEAM_LEADER(tlname);
			}

			if (am_dmName.equals("null") || am_dmName.isEmpty()) {
				System.out.println("inside nullnullnullnull");
				team.setAM_DM("NA");
			} else {
				team.setAM_DM(am_dmName);
			}

			team.setPHASE(phaseType);

			try {
				Query solnIdQ = sessionFactory.getCurrentSession().createQuery(
						"select Security_Tools from ProductMaster where SECURITY_SOLTION='" + productname + "'");
				List<String> solnIds = solnIdQ.list();
				solnId = solnIds.get(0);
			} catch (Exception e) {
				solnId = "NA";
			}

			team.setSOL_ID(solnId);

			getSession().save(team);
			status = "success";
//			}
		} catch (Exception e) {
			e.printStackTrace();
		}

		return status;

	}

