	@Override
	public JSONArray getTaskCount(String tableName, String getFrom) {

		System.out.println("tableName " + tableName);

		JSONArray array1 = new JSONArray();
		String hql = null;

		hql = "SELECT " + tableName + ", " + "COUNT(CASE WHEN STATUS != 'Total' THEN 1 END) AS totalCount, "
				+ "COUNT(CASE WHEN STATUS = 'Close' THEN 1 END) AS ClosedCount, "
				+ "COUNT(CASE WHEN STATUS != 'Close' THEN 1 END) AS OtherCount " + "FROM ComplianceTask " + "GROUP BY "
				+ tableName;

		Query query = sessionFactory.getCurrentSession().createSQLQuery(hql);

		System.out.println("queryyy " + query);

		List<Object[]> dataList = query.list();

		for (Object[] result : dataList) {

			String name = (String) result[0];
			BigInteger totalTask = (BigInteger) result[1];
			BigInteger completedTask = (BigInteger) result[2];
			BigInteger pendingTask = (BigInteger) result[3];

			JSONObject ob = new JSONObject();

			if (getFrom.equalsIgnoreCase("web")) {
				if (tableName.equalsIgnoreCase("F_HEAD")) {
					ob.put("name", "<a onclick=\"getDetailsModal1('" + name + "')\" style=\"cursor: pointer;\">" + name
							+ "</a>");
				} else {
					ob.put("name", "<a onclick=\"getDetailsBySolution1('" + name + "')\" style=\"cursor: pointer;\">"
							+ name + "</a>");
				}

			} else {
				ob.put("name", name);
			}

			ob.put("total", totalTask); // Corrected: Use totalTask
			ob.put("completed", completedTask); // Corrected: Use completedTask
			ob.put("pending", pendingTask); // Corrected: Use pendingTask

			array1.put(ob);
		}
		System.out.println("final table arrr : " + array1);

		return array1;

	}

