	@Override
	public JSONArray getTaskByName(String selectedName, String type) {

		System.out.println("tableName " + selectedName);
		String sname = URLDecoder.decode(selectedName);
		String hql = "";

		JSONArray array1 = new JSONArray();

		if (type.equalsIgnoreCase("fh")) {
			hql = "from ComplianceTask where F_HEAD = '" + sname + "' order by SR_NO desc";
		} else if (type.equalsIgnoreCase("solution")) {
			hql = "from ComplianceTask where PRODUCTTOOL = '" + sname + "' order by SR_NO desc";
		}

		Query query = sessionFactory.getCurrentSession().createQuery(hql);

		System.out.println("queryyy " + query);

		List<ComplianceTask> dataList = query.list();

		for (ComplianceTask a : dataList) {

			String soln = a.getPRODUCTTOOL();
			String fhead = a.getF_HEAD();

			String desc = a.getDESCRIPTION();
			String manager = a.getMANAGER_NAME();
			String status = a.getSTATUS();
			String targetDate = "";

			String pending = "";

			if (a.getSTATUS().equalsIgnoreCase("Assigned") || a.getSTATUS().equalsIgnoreCase("Tested")) {

				if (a.getDEVELOPER_NAME() == null || a.getDEVELOPER_NAME().contentEquals("")) {
					pending = a.getTEAM_LEADER();
				} else {
					pending = a.getDEVELOPER_NAME();
				}

			} else if (a.getSTATUS().equalsIgnoreCase("Yet To Assign")) {
				pending = a.getMANAGER_NAME();

			} else if (a.getSTATUS().equalsIgnoreCase("Ready to Deliver")) {
				if (a.getF_HEAD() == null || a.getF_HEAD().contentEquals("")) {
					pending = "NA";
				} else {
					pending = a.getF_HEAD();
				}

			} else if (a.getSTATUS().equalsIgnoreCase("Developed")) {
				pending = a.getTESTER_NAME();
			} else {
				pending = "NA";
			}

			JSONObject ob = new JSONObject();

//            if (tableName.equalsIgnoreCase("F_HEAD")) {
//                ob.put("name", name);
//            } else {

//                ob.put("name","<a onclick=\"getDetailsModal('" + name + "')\" style=\"cursor: pointer;\">" + name + "</a>");
//            }

			if (type.equalsIgnoreCase("fh")) {
				ob.put("name", soln);
			} else if (type.equalsIgnoreCase("solution")) {
				ob.put("name", fhead);
			}

			ob.put("description", desc);
			ob.put("manager", manager);

			ob.put("status", status);
			ob.put("pending", pending);

			if (a.getASSIGNED_DATE() == null || a.getASSIGNED_DATE().contentEquals("")) {
				ob.put("targetDate", "-");
			} else {
				ob.put("targetDate", a.getASSIGNED_DATE());
			}

			array1.put(ob);
		}
		System.out.println("final table arrr : " + array1);

		return array1;
	}

