	@Override
	public String updateReviseDate(String fullname, String role, String designation, String updatedEndDates,
			String updateDatesReason) {

		String status = null;

		try {
			System.out.println("updatedEndDates: " + updatedEndDates);

			String[] endData = updatedEndDates.split("~,");

			if (endData.length % 3 != 0) {
				System.out.println("Data format error: Expected sets of 3 entries for each record.");
				return "error";
			}

			for (int i = 0; i < endData.length; i += 3) {

				String srnoString = endData[i];
				int srno = Integer.parseInt(srnoString);
				String endDate = endData[i + 1];
				String reasonDec = endData[i + 2];
				String reason = URLDecoder.decode(reasonDec);
				reason = reason.replace("~", "").trim();

				String hqlUpdateStart = "update ComplianceTask set REVISE_DATE_STATUS='Pending for approval', REVISED_DATE= :endDate, REVISED_DATE_REASON= :reviseReason, DATE_APPROVED_BY=null WHERE SR_NO= :srno";
				Query updateStartQuery = sessionFactory.getCurrentSession().createQuery(hqlUpdateStart);
				updateStartQuery.setParameter("srno", srno);

				updateStartQuery.setParameter("endDate", endDate);
				updateStartQuery.setParameter("reviseReason", reason);

				int startUpdateCount = updateStartQuery.executeUpdate();
				status = (startUpdateCount > 0) ? "success" : "error";
				System.out.println(startUpdateCount > 0 ? "Start Date Updated" : "Start Date Not Updated");

			}
		} catch (NumberFormatException e) {
			System.out.println("Error parsing SR_NO to Integer: " + e.getMessage());
			status = "error";
		} catch (Exception e) {
			status = "error";
			e.printStackTrace();
		}
		return status;
	}

