	@Override
	public JSONArray getTaskLists(String userfullname, String role, String designation, String type, String value) {

		JSONArray array = null;
		JSONArray array1 = null;
		String endDate = null;
		Query q = null;
		try {

			LocalDate currentDate = LocalDate.now();
			DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd-MM-yyyy");
			String formattedDate = currentDate.format(formatter);

			array1 = new JSONArray();

			if (value.equalsIgnoreCase("All")) {

				if (type.equalsIgnoreCase("total")) {
					q = sessionFactory.getCurrentSession().createQuery("from ComplianceTask ORDER BY ASSIGNED_DATE");
				} else if (type.equalsIgnoreCase("delayed")) {
					q = sessionFactory.getCurrentSession().createQuery(
							"from ComplianceTask WHERE STATUS!='Close' AND STR_TO_DATE(ASSIGNED_DATE, '%d-%m-%Y') < CURRENT_DATE() ORDER BY ASSIGNED_DATE ");
				} else if (type.equalsIgnoreCase("closed")) {
					q = sessionFactory.getCurrentSession()
							.createQuery("from ComplianceTask WHERE STATUS='Close' ORDER BY ASSIGNED_DATE ");
				} else if (type.equalsIgnoreCase("track")) {
					q = sessionFactory.getCurrentSession().createQuery(
							"from ComplianceTask WHERE STATUS!='Close' AND (STR_TO_DATE(ASSIGNED_DATE, '%d-%m-%Y') >= CURRENT_DATE() OR ASSIGNED_DATE IS NULL OR ASSIGNED_DATE='' ) ORDER BY ASSIGNED_DATE ");
				}

			} else {

				if (type.equalsIgnoreCase("total")) {
					q = sessionFactory.getCurrentSession().createQuery(
							"from ComplianceTask WHERE ASSIGNED_DATE='" + formattedDate + "' ORDER BY ASSIGNED_DATE");
				} else if (type.equalsIgnoreCase("delayed")) {
					q = sessionFactory.getCurrentSession().createQuery(
							"from ComplianceTask WHERE STATUS!='Close' AND ASSIGNED_DATE='abc' ORDER BY ASSIGNED_DATE ");
				} else if (type.equalsIgnoreCase("closed")) {
					q = sessionFactory.getCurrentSession()
							.createQuery("from ComplianceTask WHERE STATUS='Close' AND ASSIGNED_DATE='" + formattedDate
									+ "' ORDER BY ASSIGNED_DATE ");
				} else if (type.equalsIgnoreCase("track")) {
					q = sessionFactory.getCurrentSession()
							.createQuery("from ComplianceTask WHERE STATUS!='Close' AND ASSIGNED_DATE='" + formattedDate
									+ "' ORDER BY ASSIGNED_DATE ");
				}
			}

			List<ComplianceTask> dataList = q.list();
			for (ComplianceTask a : dataList) {
				array = new JSONArray();
				array.put(a.getPRODUCTTOOL());
				array.put(a.getDESCRIPTION());

				if (a.getASSIGNED_DATE() == null || a.getASSIGNED_DATE().contentEquals("")) {
					array.put("NA");
				} else {
					array.put(a.getASSIGNED_DATE());
					endDate = a.getASSIGNED_DATE();
				}

				if (a.getTEAM_LEADER() == null || a.getTEAM_LEADER().contentEquals("")) {
					array.put("NA");
				} else {
					array.put(a.getTEAM_LEADER());
				}

				if (a.getDEVELOPER_NAME() == null || a.getDEVELOPER_NAME().contentEquals("")) {
					array.put("NA");
				} else {
					array.put(a.getDEVELOPER_NAME());
				}

				array.put(a.getSTATUS());

				if (a.getSTATUS().equalsIgnoreCase("Yet to Assign")) {

					if (a.getF_HEAD() == null || a.getF_HEAD().contentEquals("")) {
						array.put("NA");
					} else {
						array.put(a.getF_HEAD());
					}

				}
				if (a.getSTATUS().equalsIgnoreCase("Assigned")) {

					if (a.getDEVELOPER_NAME() == null || a.getDEVELOPER_NAME().contentEquals("")) {
						array.put(a.getTEAM_LEADER());
					} else {
						array.put(a.getDEVELOPER_NAME());
					}

				} else if (a.getSTATUS().equalsIgnoreCase("Ready to Deliver")) {
					if (a.getF_HEAD() == null || a.getF_HEAD().contentEquals("")) {
						array.put("NA");
					} else {
						array.put(a.getF_HEAD());
					}

				} else if (a.getSTATUS().equalsIgnoreCase("Tested")) {
					array.put(a.getTEAM_LEADER());
				} else if (a.getSTATUS().equalsIgnoreCase("Developed")) {
					array.put(a.getTESTER_NAME());
				} else {
					array.put("NA");
				}

				if (value.equalsIgnoreCase("All")
						&& (type.equalsIgnoreCase("delayed") || type.equalsIgnoreCase("total"))) {

					try {
						DateTimeFormatter formatter1 = DateTimeFormatter.ofPattern("dd-MM-yyyy");
						LocalDate endDate1 = LocalDate.parse(endDate.toString(), formatter1);
						long delayDays = ChronoUnit.DAYS.between(endDate1, LocalDate.now());

						if (delayDays > 0) {
							array.put(delayDays);
						} else {
							array.put("0");
						}
					} catch (Exception e) {
						array.put("0");
					}
				}
				array1.put(array);
			}

		} catch (Exception e) {
			e.printStackTrace();
			// TODO: handle exception
		}
		System.out.println("array1array1" + array1);
		return array1;
	}

