	@Override
	public String assignTicket(String id, String branch, String flag, String ip_add, String mail_msg, String problem,
			String subject, String r_date) {
		String status1 = null;
		try {
			Session s = getSession();
			int srno = 0;
			try {
				Criteria crit = sessionFactory.getCurrentSession().createCriteria(Assigned_Ticket.class)
						.setProjection(Projections.max("SR_NO"));
				Integer srno1 = (Integer) crit.uniqueResult();

				if (srno1 != null) {
					srno = srno1.intValue() + 1;

				} else {
					srno = 1;
				}
			} catch (Exception e) {

				e.printStackTrace();
			}

			Query query = sessionFactory.getCurrentSession().createQuery("from Assigned_Ticket where ref_id=:ref_id ");
			query.setParameter("ref_id", id);

			List data = query.list();

			if (!data.isEmpty()) {
				status1 = "duplicate";
			} else {
				Assigned_Ticket tk = new Assigned_Ticket();

				tk.setSR_NO(srno);
				tk.setBranch(branch);
				tk.setFlag(flag);
				tk.setIp_address(ip_add);
				tk.setMail_msg(mail_msg);
				tk.setProblem(problem);
				tk.setSubject(subject);
				tk.setR_date(r_date);
				tk.setRef_id(id);

				getSession().save(tk);
				status1 = "success";
			}
		} catch (Exception e) {
			status1 = "fail";
			e.printStackTrace();
		}

		return status1;
	}

