		statusList.add("Pending");
		statusList.add("Completed");
		statusList.add("Other");

		JSONArray array1 = new JSONArray();

		// daywise table

		Criteria q = sessionFactory.getCurrentSession().createCriteria(DaywiseTask.class);
		q.add(Restrictions.in("STATUS", statusList));

		List<DaywiseTask> ds = q.list();

//				JSONArray array1 = new JSONArray();
